import { memo, useState } from "react";
import type { UIMessage } from "ai";
import { cn } from "./utils/cn";
import { FileAttachment } from "./input/file-attachment";
import { ImageLightbox } from "./image-lightbox";

export type UserMessageProps = {
  message: UIMessage;
  className?: string;
  /**
   * When true (default) clicking an attached image opens a fullscreen
   * lightbox preview. Set to false to render images as plain thumbnails.
   */
  enableImagePreview?: boolean;
};

type MessagePart = UIMessage["parts"][number];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isTextPart(part: MessagePart): part is { type: "text"; text: string } {
  return (
    part.type === "text" &&
    typeof (part as { text?: unknown }).text === "string"
  );
}

function getImageUrlFromPart(part: unknown): string | null {
  if (!isRecord(part)) return null;
  const type = part.type;
  if (typeof type !== "string") return null;

  if (type === "image") {
    const imagePart = part as { url?: string; image?: string };
    return imagePart.url ?? imagePart.image ?? null;
  }

  if (type === "data-image") {
    const dataPart = part as { data?: { url?: string } };
    return dataPart.data?.url ?? null;
  }

  if (type === "file") {
    const filePart = part as { mimeType?: string; url?: string; data?: string };
    if (filePart.mimeType?.startsWith("image/")) {
      if (filePart.url) return filePart.url;
      if (filePart.data) {
        return `data:${filePart.mimeType};base64,${filePart.data}`;
      }
    }
  }

  return null;
}

type FilePart = {
  type: "file";
  filename?: string;
  name?: string;
  fileName?: string;
  size?: number;
  mimeType?: string;
  url?: string;
};

function getFileFromPart(part: unknown) {
  if (!isRecord(part)) return null;
  if (part.type !== "file") return null;
  const filePart = part as FilePart;
  const filename =
    filePart.filename || filePart.name || filePart.fileName || "Attachment";
  const isImage = filePart.mimeType?.startsWith("image/") ?? false;
  if (isImage) return null;
  return {
    filename,
    size: filePart.size,
  };
}

export const UserMessage = memo(function UserMessage({
  message,
  className,
  enableImagePreview = true,
}: UserMessageProps) {
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);
  const textParts = message.parts?.filter(isTextPart) ?? [];
  const text = textParts.map((p) => p.text).join("");

  const images: string[] = [];
  const files: Array<{ filename: string; size?: number }> = [];
  for (const part of message.parts ?? []) {
    const imageUrl = getImageUrlFromPart(part);
    if (imageUrl) images.push(imageUrl);
    const file = getFileFromPart(part);
    if (file) files.push(file);
  }
  if (isRecord(message) && Array.isArray(message.experimental_attachments)) {
    for (const att of message.experimental_attachments as Array<{
      contentType?: string;
      url?: string;
    }>) {
      if (att.contentType?.startsWith("image/") && att.url) {
        images.push(att.url);
      }
    }
  }

  if (!text && images.length === 0 && files.length === 0) return null;

  const lightboxImages = images.map((url, i) => ({
    id: `${message.id}-img-${i}`,
    url,
    filename: `image-${i + 1}`,
  }));

  return (
    <div className={cn("flex flex-col items-end gap-1", className)}>
      {images.length > 0 &&
        images.map((url, i) => (
          <div
            key={i}
            className={cn(
              "max-w-[200px] p-1.5 bg-an-foreground/4 rounded-an-message",
              enableImagePreview && "cursor-pointer",
            )}
            onClick={
              enableImagePreview ? () => setLightboxIndex(i) : undefined
            }
          >
            <img
              src={url}
              alt="attachment"
              className="block object-cover max-w-[184px] max-h-[120px] rounded-an-message-inner"
            />
          </div>
        ))}
      {enableImagePreview && lightboxImages.length > 0 && (
        <ImageLightbox
          open={lightboxIndex !== null}
          onClose={() => setLightboxIndex(null)}
          images={lightboxImages}
          initialIndex={lightboxIndex ?? 0}
        />
      )}
      {files.length > 0 && (
        <div className="flex flex-col items-end gap-2">
          {files.map((file, i) => (
            <FileAttachment
              key={`${file.filename}-${i}`}
              id={`${file.filename}-${i}`}
              filename={file.filename}
              size={file.size}
            />
          ))}
        </div>
      )}
      {text && (
        <div className="max-w-[calc(95%-40px)] ms-[70px]">
          <div className="px-3.5 py-1.5 text-sm transition-colors rounded-an-message bg-an-user-message-bg text-an-user-message-text">
            <p className="leading-5 whitespace-pre-wrap wrap-break-word">
              {text}
            </p>
          </div>
        </div>
      )}
    </div>
  );
});

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { createPortal } from "react-dom";
import {
  IconChevronLeft,
  IconChevronRight,
  IconX,
} from "@tabler/icons-react";
import { cn } from "./utils/cn";

export type LightboxImage = {
  /** Stable identifier — used for keys and to know which image is active. */
  id: string;
  /** Resolvable image URL (https / data: / blob:). */
  url: string;
  /** Optional filename used for the alt text. */
  filename?: string;
};

export type ImageLightboxProps = {
  /** Whether the overlay is open. */
  open: boolean;
  /** Close handler — wired to overlay click, X button, and Esc key. */
  onClose: () => void;
  /** Full set of images for gallery navigation. */
  images: LightboxImage[];
  /** Index in `images` to start on. */
  initialIndex?: number;
};

/**
 * Portal-based fullscreen image preview. Renders to `document.body` so it
 * escapes any clipping/transform/stacking context. Adapted from the
 * 21st-private-1 desktop chat — without copy/save (those are
 * desktop-API-specific).
 */
export function ImageLightbox({
  open,
  onClose,
  images,
  initialIndex = 0,
}: ImageLightboxProps) {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);
  const hasMultipleImages = images.length > 1;

  // Sync the active index whenever the consumer re-opens with a new initial.
  useEffect(() => {
    if (open) setCurrentIndex(initialIndex);
  }, [open, initialIndex]);

  const goToPrevious = useCallback(
    (event?: React.MouseEvent) => {
      event?.stopPropagation();
      setCurrentIndex((prev) => (prev > 0 ? prev - 1 : images.length - 1));
    },
    [images.length],
  );

  const goToNext = useCallback(
    (event?: React.MouseEvent) => {
      event?.stopPropagation();
      setCurrentIndex((prev) => (prev < images.length - 1 ? prev + 1 : 0));
    },
    [images.length],
  );

  // Esc / arrow-key navigation. Capture phase so we beat any local handlers
  // (e.g. an Editor that swallows Esc).
  useEffect(() => {
    if (!open) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      switch (event.key) {
        case "Escape":
          event.preventDefault();
          event.stopPropagation();
          onClose();
          break;
        case "ArrowLeft":
          if (hasMultipleImages) goToPrevious();
          break;
        case "ArrowRight":
          if (hasMultipleImages) goToNext();
          break;
      }
    };
    window.addEventListener("keydown", handleKeyDown, true);
    return () =>
      window.removeEventListener("keydown", handleKeyDown, true);
  }, [open, hasMultipleImages, onClose, goToPrevious, goToNext]);

  // Lock body scroll while open so the page underneath doesn't move.
  useEffect(() => {
    if (!open) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, [open]);

  if (typeof document === "undefined") return null;
  if (!open) return null;
  const currentImage = images[currentIndex] ?? images[0];
  if (!currentImage?.url) return null;

  return createPortal(
    <div
      role="dialog"
      aria-modal="true"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm"
      onClick={onClose}
    >
      <button
        type="button"
        onClick={onClose}
        aria-label="Close fullscreen (Esc)"
        className="absolute top-4 right-4 z-10 inline-flex size-9 items-center justify-center rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors"
      >
        <IconX className="size-5" />
      </button>

      {hasMultipleImages && (
        <button
          type="button"
          onClick={goToPrevious}
          aria-label="Previous image (←)"
          className="absolute left-4 top-1/2 z-10 inline-flex size-10 -translate-y-1/2 items-center justify-center rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors"
        >
          <IconChevronLeft className="size-6" />
        </button>
      )}

      <img
        src={currentImage.url}
        alt={currentImage.filename ?? "Image preview"}
        className="max-w-[90vw] max-h-[85vh] object-contain select-none"
        onClick={(event) => event.stopPropagation()}
        draggable={false}
      />

      {hasMultipleImages && (
        <button
          type="button"
          onClick={goToNext}
          aria-label="Next image (→)"
          className="absolute right-4 top-1/2 z-10 inline-flex size-10 -translate-y-1/2 items-center justify-center rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors"
        >
          <IconChevronRight className="size-6" />
        </button>
      )}

      {hasMultipleImages && (
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex flex-col items-center gap-3">
          <div className="flex gap-2">
            {images.map((_, idx) => (
              <button
                key={idx}
                type="button"
                onClick={(event) => {
                  event.stopPropagation();
                  setCurrentIndex(idx);
                }}
                aria-label={`Go to image ${idx + 1}`}
                className={cn(
                  "size-2 rounded-full transition-all",
                  idx === currentIndex
                    ? "bg-white scale-125"
                    : "bg-white/40 hover:bg-white/60",
                )}
              />
            ))}
          </div>
          <span className="text-white/70 text-sm">
            {currentIndex + 1} / {images.length}
          </span>
        </div>
      )}
    </div>,
    document.body,
  );
}

/* Agent Elements tokens + utilities */

/*
 * AN Agent Chat - CSS Custom Properties
 * These are the default values. Override by redefining these vars in your app CSS.
 */
:root {
  /* Geometry — all radii derive from --an-border-radius */
  --an-border-radius: 16px;
  --an-message-border-radius: var(--an-border-radius);
  --an-input-border-radius: var(--an-border-radius);
  --an-tool-border-radius: 10px;
  --an-message-radius-inner-offset: 4px;
  --an-max-width: 420px;

  /* Colors - Light mode defaults */
  --an-background: #ffffff;
  --an-background-secondary: #f0f0f0;
  --an-background-tertiary: #f8f8f8;
  --an-foreground: #1a1a1a;
  --an-foreground-muted: #737373;
  --an-foreground-subtle: #a3a3a3;
  --an-border-color: #e4e4e7;
  --an-primary-color: #3b82f6;

  /* User Messages */
  --an-user-message-bg: #f5f5f5;
  --an-user-message-text: #1a1a1a;

  /* Input */
  --an-input-background: #ffffff;
  --an-input-border-color: #e4e4e7;
  --an-input-color: #1a1a1a;
  --an-input-placeholder-color: #a3a3a3;
  --an-input-focus-outline: transparent;
  --an-context-padding: 10px;

  /* Send/Stop Buttons */
  --an-send-button-bg: #3b82f6;
  --an-send-button-color: #ffffff;

  /* Tools */
  --an-tool-background: #f5f5f5;
  --an-tool-border-color: #e4e4e7;
  --an-tool-color: #1a1a1a;
  --an-tool-color-muted: #737373;

  /* Code */
  --an-code-background: #1e1e1e;
  --an-code-color: #d4d4d4;

  /* Diff colors */
  --an-diff-added-bg: rgba(34, 197, 94, 0.1);
  --an-diff-added-border: rgba(34, 197, 94, 0.5);
  --an-diff-added-text: #15803d;
  --an-diff-removed-bg: rgba(239, 68, 68, 0.1);
  --an-diff-removed-border: rgba(239, 68, 68, 0.5);
  --an-diff-removed-text: #dc2626;
}

/* Dark mode defaults */
.dark {
  --an-background: #0a0a0a;
  --an-background-secondary: #242424;
  --an-background-tertiary: #141414;
  --an-foreground: #fafafa;
  --an-foreground-muted: #8c8c8c;
  --an-foreground-subtle: #71717a;
  --an-border-color: #2a2a2a;
  --an-primary-color: #60a5fa;

  --an-user-message-bg: #1a1a1a;
  --an-user-message-text: #fafafa;

  --an-input-background: #0a0a0a;
  --an-input-border-color: #2a2a2a;
  --an-input-color: #fafafa;
  --an-input-placeholder-color: #71717a;
  --an-input-focus-outline: transparent;
  --an-context-padding: 12px;

  --an-send-button-bg: #60a5fa;
  /* Dark mode uses a lighter primary (#60a5fa) — pair it with black text so
     labels like "Approve" / send-arrow have proper contrast instead of
     low-contrast white-on-light-blue. */
  --an-send-button-color: #0a0a0a;

  --an-tool-background: #141414;
  --an-tool-border-color: #2a2a2a;
  --an-tool-color: #fafafa;
  --an-tool-color-muted: #8c8c8c;

  --an-code-background: #0a0a0a;
  --an-code-color: #d4d4d4;

  --an-diff-added-bg: rgba(34, 197, 94, 0.15);
  --an-diff-added-border: rgba(34, 197, 94, 0.4);
  --an-diff-added-text: #4ade80;
  --an-diff-removed-bg: rgba(239, 68, 68, 0.15);
  --an-diff-removed-border: rgba(239, 68, 68, 0.4);
  --an-diff-removed-text: #f87171;
}

@theme inline {
  --color-an-background: var(--an-background);
  --color-an-background-secondary: var(--an-background-secondary);
  --color-an-background-tertiary: var(--an-background-tertiary);
  --color-an-foreground: var(--an-foreground);
  --color-an-foreground-muted: var(--an-foreground-muted);
  --color-an-foreground-subtle: var(--an-foreground-subtle);
  --color-an-border-color: var(--an-border-color);
  --color-an-primary-color: var(--an-primary-color);
  --color-an-user-message-bg: var(--an-user-message-bg);
  --color-an-user-message-text: var(--an-user-message-text);
  --color-an-input-background: var(--an-input-background);
  --color-an-input-border-color: var(--an-input-border-color);
  --color-an-input-color: var(--an-input-color);
  --color-an-input-placeholder-color: var(--an-input-placeholder-color);
  --color-an-input-focus-outline: var(--an-input-focus-outline);
  --color-an-send-button-bg: var(--an-send-button-bg);
  --color-an-send-button-color: var(--an-send-button-color);
  --color-an-tool-background: var(--an-tool-background);
  --color-an-tool-border-color: var(--an-tool-border-color);
  --color-an-tool-color: var(--an-tool-color);
  --color-an-tool-color-muted: var(--an-tool-color-muted);
  --color-an-code-background: var(--an-code-background);
  --color-an-code-color: var(--an-code-color);
  --color-an-diff-added-bg: var(--an-diff-added-bg);
  --color-an-diff-added-border: var(--an-diff-added-border);
  --color-an-diff-added-text: var(--an-diff-added-text);
  --color-an-diff-removed-bg: var(--an-diff-removed-bg);
  --color-an-diff-removed-border: var(--an-diff-removed-border);
  --color-an-diff-removed-text: var(--an-diff-removed-text);
  --radius-an-message: var(--an-message-border-radius);
  --radius-an-message-inner: calc(
    var(--an-message-border-radius) - var(--an-message-radius-inner-offset)
  );
  --radius-an-input-border-radius: var(--an-input-border-radius);
  --radius-an-tool-border-radius: var(--an-tool-border-radius);
  --spacing-an-context-padding: var(--an-context-padding);
  --max-width-an: var(--an-max-width);
  --spacing-an-user-message-x: 14px;
  --spacing-an-user-message-y: 10px;
}

/* TextShimmer animation */
@keyframes an-shimmer {
  from {
    background-position: 100% center;
  }
  to {
    background-position: 0% center;
  }
}

@keyframes an-blink {
  50% {
    opacity: 0;
  }
}

@keyframes loading-dots {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

@keyframes an-ellipsis {
  0% {
    width: 0;
  }
  33% {
    width: 0.33em;
  }
  66% {
    width: 0.66em;
  }
  100% {
    width: 1em;
  }
}

.an-text-shimmer {
  display: inline-block;
  background-size: 250% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  background-image: linear-gradient(
    90deg,
    var(--an-foreground-subtle, #a3a3a3) 0%,
    var(--an-foreground-subtle, #a3a3a3) 40%,
    var(--an-foreground-muted, #737373) 50%,
    var(--an-foreground-subtle, #a3a3a3) 60%,
    var(--an-foreground-subtle, #a3a3a3) 100%
  );
  background-repeat: no-repeat;
}

.an-text-shimmer--active {
  animation: an-shimmer var(--an-shimmer-duration, 2s) linear infinite;
}

.an-ellipsis {
  display: inline-block;
  overflow: hidden;
  width: 0;
  vertical-align: bottom;
  animation: an-ellipsis 1.2s steps(1, end) infinite;
}

.an-markdown pre code {
  counter-reset: none !important;
}

.an-markdown pre code > span::before {
  content: none !important;
  display: none !important;
}

.an-markdown pre code > span {
  padding-left: 0 !important;
}

/* Diff */
.an-edit-diff,
.an-edit-diff pre,
.an-edit-diff code {
  font-size: 12px;
}

.dark .an-edit-tool-card {
  background-color: #000;
}

[data-theme="dark"] .an-edit-tool-card {
  background-color: #000;
}

.dark .an-edit-tool-card .an-edit-diff,
.dark .an-edit-tool-card .an-edit-diff pre,
.dark .an-edit-tool-card .an-edit-diff code {
  background-color: #000 !important;
}

[data-theme="dark"] .an-edit-tool-card .an-edit-diff,
[data-theme="dark"] .an-edit-tool-card .an-edit-diff pre,
[data-theme="dark"] .an-edit-tool-card .an-edit-diff code {
  background-color: #000 !important;
}

/* Markdown Code Block */
.an-markdown [data-streamdown="code-block"] {
  padding: 0;
  border: 1px solid var(--an-border-color);
  border-radius: var(--an-tool-border-radius);
  background: transparent;
  gap: 0;
}

.an-markdown [data-streamdown="code-block-header"] {
  padding: 0px 10px 0px 8px;
  height: auto;
  font-size: 12px;
  height: 28px;
  background: transparent;
  border-bottom: 1px solid var(--color-an-tool-border-color);
  background-color: var(--an-tool-background);
  position: relative;
}

.an-markdown div:has(> [data-streamdown="code-block-actions"]) {
  position: absolute;
  height: auto;
  margin: 0;
  top: 0;
  right: 0;
  height: 28px;
  padding-right: 8px;
}

.an-markdown [data-streamdown="code-block-actions"] {
  background: transparent;
  border: none;
  backdrop-filter: none;
  padding: 0;
}

.an-markdown [data-streamdown="code-block-actions"] button > svg {
  width: 14px;
  height: 14px;
}

.an-markdown [data-streamdown="code-block-body"] {
  margin: 0;
  padding-top: 8px;
  padding-bottom: 8px;
  background: transparent;
  border: transparent;
  overflow-x: auto;
}

.an-markdown [data-streamdown="code-block"] pre,
.an-markdown [data-streamdown="code-block"] code {
  font-size: 12px;
  background: transparent;
}
